let S;

function setup() {
	createCanvas(windowWidth, windowHeight);
	S = max(width, height);
	noFill();
	stroke("deeppink");
	strokeWeight(2);
}

function draw() {
	background("#00006020");
	translate(width/2, height/2);

	const t = millis()/1000/2;
	dia = S * 0.8;
	dd = 0.4;
	const a1 = (noise(t, 100) - 0.5) / 4
	const a2 = (noise(t, 200) - 0.5) / 3
	const a3 = (noise(t, 300) - 0.5) / 2
	noStroke();
	fill("#FFBFCA80");
	fill("#FF149210");
	drawCirc(0, 0, dia, a1, 30); // arc(0, 0, dia, dia, dd/10+a1, TAU-dd/10+a1);
	drawCirc(-dia/6, 0, dia/1.5, a2, 20); // arc(-dia/6, 0, dia/1.5, dia/1.5, PI+dd+a2, 1.5*TAU-dd+a2)
	drawCirc(0, 0, dia/3, a3, 10); // arc(0, 0, dia/3, dia/3, dd+a3, TAU-dd+a3)
}

function drawCirc(x, y, s, a, n, f = 0.333) {
	push();
	translate(x, y);
	rotate(a)
	beginClip();
	circle(0, 0, s)
	endClip();
	const w = s / (n+f)
	const x1 = w * f
	const x2 = w - x1

	for (let i = 0, x = -s/2; i <= n; i++, x += w) {
		rect(x, -height/2, x1, height)
	}
	pop();
}
